t.script:
function showFields(type) {
    var types = ['yacht', 'jet', 'hotel', 'voiture'];
    types.forEach(function(t) {
        var el = document.getElementById('fields_' + t);
        if (el) el.style.display = (t === type) ? 'block' : 'none';
    });
}
// Restaurer si erreur formulaire
var typeBien = document.getElementById('type_bien');
if (typeBien && typeBien.value) showFields(typeBien.value);
